<form id="lookup-form" method="get" action="{{ route('admin.voucher') }}"><div class="field"><label for="code">Kode atau link voucher</label><input id="code" name="code" required maxlength="300" value="{{ old('code') }}" autocomplete="off" autocapitalize="characters" spellcheck="false"><p class="hint">Scan hanya membuka preview. Klaim perlu konfirmasi tersendiri.</p></div><div class="actions"><button class="button" type="submit">Periksa voucher</button><div class="scanner"><div class="scanner-actions"><button class="button secondary" type="button" data-start-scanner aria-controls="scanner-preview">Scan dengan kamera</button><button class="button secondary" type="button" data-stop-scanner hidden>Hentikan kamera</button></div><div id="scanner-preview" class="scanner-preview" data-scan-preview hidden><video muted playsinline aria-label="Pratinjau kamera pemindai voucher"></video></div><p id="scanner-status" class="hint" role="status"></p></div></div></form>
